const out = [];
for (const item of $input.all()) {
  const e = item.json.body || {};
  const d = e.data || {};
  const who = [d.name, d.biz].filter(Boolean).join(' · ');
  const app = 'https://app.simple-solution.co.il';
  let subject = '', text = '';
  if (e.event === 'lead_created') { subject = 'ליד חדש: ' + who; text = `${who}\nטלפון: ${d.phone || '-'}\nמקור: ${d.source || '-'}${d.campaign ? ' · ' + d.campaign : ''}\n\n${app}/leads/${d.id}`; }
  else if (e.event === 'lead_returned') { subject = 'פנייה חוזרת: ' + who; text = `${who} השאיר/ה פרטים שוב.\n\n${app}/leads/${d.id}`; }
  else if (e.event === 'quote_viewed') { subject = 'הצעה ' + d.no + ' נפתחה'; text = `${who} פתח/ה את הצעה ${d.no}.\n\n${app}/quotes/${d.id}`; }
  else if (e.event === 'quote_signed') { subject = 'הצעה ' + d.no + ' נחתמה!'; text = `${who} חתם/ה על הצעה ${d.no}.\nלחודש: ${Math.round(d.totals?.monthly || 0).toLocaleString('he-IL')} ₪ · חד פעמי: ${Math.round(d.totals?.oneoff || 0).toLocaleString('he-IL')} ₪ (לפני מע"מ)\n\nהלקוח, השירותים, התשלום ורשימת הקליטה כבר נפתחו.\n${app}/quotes/${d.id}`; }
  else if (e.event === 'quote_rejected') { subject = 'הצעה ' + d.no + ' נדחתה'; text = `${who} סימן/ה שההצעה לא מתאימה כרגע.\n\n${app}/quotes/${d.id}`; }
  else continue;
  out.push({ json: { subject, text } });
}
return out;
